'use strict';
/**
 * Offline byte-fidelity verification against an operator-supplied,
 * first-party lab document manifest. Only sizes/hashes are reported:
 * never prints response content, cookies, passwords or URL parameters.
 *
 * Manifest must be generated by the test server from its own static
 * documents. This tool does not authenticate the manifest or claim
 * comprehensive HTTP traffic capture.
 */
const fs=require('node:fs/promises');
const path=require('node:path');
const crypto=require('node:crypto');
const {validateSafeFileName}=require('./almacen-original-files.js');
const {validateProfileId,isAbsoluteLocalFolder}=
  require('./almacen-perfil-readonly.js');

const SHA=/^[a-f0-9]{64}$/;
async function verifyTestManifest({rootFolder,profileId,manifest}) {
  if(!isAbsoluteLocalFolder(rootFolder))throw Error('ROOT_INVALID');
  validateProfileId(profileId);
  if(!Array.isArray(manifest)||manifest.length<1||manifest.length>1000)
    throw Error('MANIFEST_INVALID');
  const expected=[];
  for(const row of manifest){
    if(!row||typeof row!=='object')throw Error('MANIFEST_INVALID');
    validateSafeFileName(row.name);
    if(!Number.isSafeInteger(row.byteLength)||row.byteLength<0||
       row.byteLength>32*1024*1024||
       typeof row.sha256!=='string'||!SHA.test(row.sha256))
      throw Error('MANIFEST_INVALID');
    expected.push({name:row.name,size:row.byteLength,sha256:row.sha256});
  }
  // Never resolve a path supplied by the remote server itself.
  const root=path.join(rootFolder,profileId,'archivos');
  const available=[];
  const dirs=await fs.readdir(root,{withFileTypes:true}).catch(error=>{
    if(error.code==='ENOENT')return [];throw error
  });
  for(const entry of dirs){
    if(!entry.isDirectory()||entry.isSymbolicLink())continue;
    const event=path.join(root,entry.name);
    const children=await fs.readdir(event,{withFileTypes:true});
    for(const item of children){
      if(!item.isFile()||item.isSymbolicLink())continue;
      validateSafeFileName(item.name);
      const name=item.name;
      const full=path.join(event,name);
      const stat=await fs.lstat(full);
      if(!stat.isFile()||stat.isSymbolicLink()||stat.size>32*1024*1024)
        continue;
      const bytes=await fs.readFile(full);
      available.push({
        name,size:bytes.length,sha256:crypto.createHash('sha256').update(bytes).digest('hex')
      });
    }
  }
  let matched=0;
  let modified=0;
  const consumed=new Set();
  for(const doc of expected){
    let found=-1;
    for(let i=0;i<available.length;i++){
      const a=available[i];
      if(!consumed.has(i)&&a.name===doc.name&&a.size===doc.size&&a.sha256===doc.sha256){
        found=i;break;
      }
    }
    if(found>=0){consumed.add(found);matched++;continue}
    if(available.some((a,i)=>!consumed.has(i)&&a.name===doc.name))modified++;
  }
  return Object.freeze({
    kind:'first-party-laboratory-document-comparison',
    profileId,
    expected:expected.length,
    matched,
    missingOrChanged:expected.length-matched,
    sameNameDifferentBytes:modified,
    extraSaved:available.length-consumed.size,
    complete:matched===expected.length,
    manifestAuthenticatedByTool:false,
    onlyOperatorApprovedTestDocuments:true,
    fullNetworkTrafficVerified:false
  });
}
module.exports={verifyTestManifest};
